//! Print the whole conformance matrix in one pass: every host, every body, and
//! what each one said.
//!
//! The `#[test]`s generated by `test_host!` are the CI interface — one named test
//! per (host, body). This is the human interface: run it when a suite is failing
//! and you want the whole picture at once instead of one assertion at a time.
//!
//! ```text
//! cargo run -p gitiup-host-tests --example report --features s3,github
//! ```

use gitiup_host_tests::{hosts, report, runner, summary};

fn main() {
    let mut failing = 0usize;
    let mut ran_anything = false;
    for host in hosts::all() {
        println!("{}", summary(host));
        let lines = report(host);
        if lines.is_empty() {
            println!("    all bodies passed");
            ran_anything = true;
            continue;
        }
        for line in lines {
            if line.starts_with("SKIP") || line.contains(": SKIP (") {
                println!("    {line}");
                continue;
            }
            failing += 1;
            ran_anything = true;
            println!("    FAIL {line}");
        }
    }

    // The claim that is not about one host: a change published on a bucket, read and
    // merged through a plain-git host, with the same digests from both. It is not a body
    // — a body is one host measured once — so it gets its own lines here, its own test
    // file, and its own named step in CI.
    println!("\ncross-host (publish on the bucket, merge through the git host)");
    for (name, publisher, merger) in hosts::cross_pairs() {
        match runner::cross_report(name, publisher, merger) {
            None => {
                println!("    {name}: passed");
                ran_anything = true;
            }
            Some(line) if line.contains(": SKIP (") => println!("    {line}"),
            Some(line) => {
                failing += 1;
                ran_anything = true;
                println!("    FAIL {line}");
            }
        }
    }

    if !ran_anything {
        println!("nothing ran: every host was unavailable");
    }
    if failing > 0 {
        println!("\n{failing} body/host combinations failed");
        std::process::exit(1);
    }
    println!("\nevery host that could run, conformed");
}
